const readEnvironmentCacheScheduleEvents = `-- name: ReadEnvironmentCacheScheduleEvents :many
SELECT scope,to_jsonb(payload || jsonb_build_object('sequence',sequence,'occurred_at',occurred_at)) AS event
FROM environment_cache_schedule_events WHERE account_id=$1::uuid AND app_id=$2::uuid AND environment_id=$3::uuid AND sequence>$4::bigint
ORDER BY sequence LIMIT $5::int
`

type ReadEnvironmentCacheScheduleEventsParams struct {
	AccountID     pgtype.UUID
	AppID         pgtype.UUID
	EnvironmentID pgtype.UUID
	AfterSequence int64
	PageLimit     int32
}

type ReadEnvironmentCacheScheduleEventsRow struct {
	Scope string
	Event []byte
}

func (q *Queries) ReadEnvironmentCacheScheduleEvents(ctx context.Context, db DBTX, arg ReadEnvironmentCacheScheduleEventsParams) ([]ReadEnvironmentCacheScheduleEventsRow, error) {
	rows, err := db.Query(ctx, readEnvironmentCacheScheduleEvents,
		arg.AccountID,
		arg.AppID,
		arg.EnvironmentID,
		arg.AfterSequence,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReadEnvironmentCacheScheduleEventsRow{}
	for rows.Next() {
		var i ReadEnvironmentCacheScheduleEventsRow
		if err := rows.Scan(&i.Scope, &i.Event); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const recordEnvironmentCacheGatewayObserved = `-- name: RecordEnvironmentCacheGatewayObserved :execrows
INSERT INTO environment_cache_gateway_observations(node_id,app_id,environment_id,session_id,revision)
SELECT n.id,p.app_id,p.environment_id,s.session_id,p.revision
FROM project_environment_cache_policies p JOIN environment_cache_gateway_sessions s ON s.session_id=$1::uuid
JOIN compute_nodes n ON n.id=s.node_id
JOIN apps a ON a.id=p.app_id AND a.account_id=p.account_id AND a.project_id=p.project_id AND a.status<>'deleted'
JOIN project_environments e ON e.id=p.environment_id AND e.project_id=a.project_id AND e.account_id=a.account_id
WHERE n.name=$2::text AND n.active AND n.role IN ('compute-only','compute-node') AND n.gateway_target_url=s.gateway_target_url
AND s.heartbeat_at BETWEEN clock_timestamp()-interval '90 seconds' AND clock_timestamp()
AND p.app_id=$3::uuid AND p.environment_id=$4::uuid AND p.revision=$5::bigint
ON CONFLICT(node_id,app_id,environment_id) DO UPDATE SET session_id=excluded.session_id,revision=excluded.revision,observed_at=clock_timestamp()
`

type RecordEnvironmentCacheGatewayObservedParams struct {
	SessionID     pgtype.UUID
	NodeName      string
	AppID         pgtype.UUID
	EnvironmentID pgtype.UUID
	Revision      int64
}

func (q *Queries) RecordEnvironmentCacheGatewayObserved(ctx context.Context, db DBTX, arg RecordEnvironmentCacheGatewayObservedParams) (int64, error) {
	result, err := db.Exec(ctx, recordEnvironmentCacheGatewayObserved,
		arg.SessionID,
		arg.NodeName,
		arg.AppID,
		arg.EnvironmentID,
		arg.Revision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

